import React from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

const StyledEyebrow = styled.div`
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: ${theme.colors.mainTextMuted};
  display: inline-flex;
  align-items: center;
  gap: 8px;
`;

export interface EyebrowProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
}

export function Eyebrow({ children, ...rest }: EyebrowProps) {
  return <StyledEyebrow {...rest}>{children}</StyledEyebrow>;
}
