import React, { useEffect, useRef } from 'react';
import { EditorView, basicSetup } from 'codemirror';
import { EditorState } from '@codemirror/state';
import { oneDark } from '@codemirror/theme-one-dark';
import { html } from '@codemirror/lang-html';
import { css } from '@codemirror/lang-css';
import { javascript } from '@codemirror/lang-javascript';
import { indentWithTab } from '@codemirror/commands';
import { keymap } from '@codemirror/view';
import { theme as appTheme } from '@atlantis/shared';

type Lang = 'html' | 'css' | 'js' | 'ts' | 'react';

interface CodeEditorProps {
  value: string;
  onChange: (value: string) => void;
  lang: Lang;
}

function getLangExtension(lang: Lang) {
  switch (lang) {
    case 'html': return html();
    case 'css': return css();
    case 'ts': return javascript({ typescript: true });
    case 'react': return javascript({ jsx: true, typescript: true });
    case 'js':
    default: return javascript();
  }
}

const editorTheme = EditorView.theme({
  '&': {
    flex: '1',
    minHeight: '0',
    height: '100%',
    fontSize: '13px',
    fontFamily: "'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace",
    background: appTheme.colors.mainBg,
  },
  '.cm-scroller': {
    overflow: 'auto',
    lineHeight: '1.7',
    fontFamily: 'inherit',
  },
  '.cm-content': {
    padding: '16px',
    caretColor: appTheme.colors.accent,
  },
  '.cm-gutters': {
    background: appTheme.colors.mainBg,
    border: 'none',
    borderRight: `1px solid ${appTheme.colors.border}`,
    color: appTheme.colors.sidebarTextMuted,
  },
  '.cm-activeLineGutter': {
    background: 'transparent',
  },
  '.cm-activeLine': {
    background: 'rgba(88,166,255,0.04)',
  },
  '.cm-selectionBackground, ::selection': {
    background: 'rgba(88,166,255,0.2) !important',
  },
  '.cm-cursor': {
    borderLeftColor: appTheme.colors.accent,
  },
  '&::-webkit-scrollbar': { width: '6px', height: '6px' },
  '&::-webkit-scrollbar-track': { background: 'transparent' },
  '&::-webkit-scrollbar-thumb': { background: appTheme.colors.border, borderRadius: '3px' },
});

export default function CodeEditor({ value, onChange, lang }: CodeEditorProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Recreate the editor when lang changes
  useEffect(() => {
    if (!containerRef.current) return;

    const view = new EditorView({
      state: EditorState.create({
        doc: value,
        extensions: [
          basicSetup,
          oneDark,
          editorTheme,
          getLangExtension(lang),
          keymap.of([indentWithTab]),
          EditorView.updateListener.of((update) => {
            if (update.docChanged) {
              onChangeRef.current(update.state.doc.toString());
            }
          }),
        ],
      }),
      parent: containerRef.current,
    });

    viewRef.current = view;
    return () => {
      view.destroy();
      viewRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lang]);

  // Sync external value changes without recreating the editor
  useEffect(() => {
    const view = viewRef.current;
    if (!view) return;
    const current = view.state.doc.toString();
    if (current !== value) {
      view.dispatch({
        changes: { from: 0, to: current.length, insert: value },
      });
    }
  }, [value]);

  return (
    <div
      ref={containerRef}
      style={{
        flex: 1,
        minHeight: 0,
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
      }}
    />
  );
}
