import React from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

export type ButtonVariant =
  | 'ghost'    // transparent + muted border — New / Format / Minify / Examples ▾
  | 'accent'   // transparent + accent border — Save / secondary actions
  | 'primary'  // solid accent fill — Generate / Send
  | 'success'  // solid green fill — Run
  | 'danger';  // solid red fill — destructive actions

export type ButtonSize = 'sm' | 'md';

interface StyledBtnProps {
  variant: ButtonVariant;
  size: ButtonSize;
}

/* ── Variant → colour maps ─────────────────────────────────────────── */

const VARIANT_BG: Record<ButtonVariant, string> = {
  ghost:   'transparent',
  accent:  'transparent',
  primary: theme.colors.accent,
  success: '#238636',
  danger:  '#da3633',
};

const VARIANT_HOVER_BG: Record<ButtonVariant, string> = {
  ghost:   theme.colors.sidebarHover,
  accent:  'rgba(88,166,255,0.10)',
  primary: theme.colors.accentHover,
  success: '#2ea043',
  danger:  '#f85149',
};

const VARIANT_BORDER: Record<ButtonVariant, string> = {
  ghost:   theme.colors.border,
  accent:  theme.colors.accent,
  primary: theme.colors.accent,
  success: '#238636',
  danger:  '#da3633',
};

const VARIANT_COLOR: Record<ButtonVariant, string> = {
  ghost:   theme.colors.mainTextMuted,
  accent:  theme.colors.accent,
  primary: '#fff',
  success: '#fff',
  danger:  '#fff',
};

const VARIANT_HOVER_COLOR: Record<ButtonVariant, string> = {
  ghost:   theme.colors.mainText,
  accent:  theme.colors.accent,
  primary: '#fff',
  success: '#fff',
  danger:  '#fff',
};

const SIZE_HEIGHT: Record<ButtonSize, string> = { sm: '28px', md: '30px' };
const SIZE_PADDING: Record<ButtonSize, string> = { sm: '0 10px', md: '0 12px' };
const SIZE_FONT: Record<ButtonSize, string> = { sm: '12px', md: '12px' };

const StyledBtn = styled.button<StyledBtnProps>`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: ${({ size }) => SIZE_HEIGHT[size]};
  padding: ${({ size }) => SIZE_PADDING[size]};
  background: ${({ variant }) => VARIANT_BG[variant]};
  border: 1px solid ${({ variant }) => VARIANT_BORDER[variant]};
  border-radius: ${theme.borderRadius.sm};
  color: ${({ variant }) => VARIANT_COLOR[variant]};
  font-size: ${({ size }) => SIZE_FONT[size]};
  font-family: ${theme.typography.fontFamily};
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
  white-space: nowrap;
  user-select: none;

  &:hover:not(:disabled) {
    background: ${({ variant }) => VARIANT_HOVER_BG[variant]};
    color: ${({ variant }) => VARIANT_HOVER_COLOR[variant]};
    border-color: ${({ variant }) =>
      variant === 'ghost' ? theme.colors.accent : VARIANT_BORDER[variant]};
  }

  &:focus-visible {
    outline: 2px solid ${theme.colors.accent};
    outline-offset: 2px;
  }

  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }
`;

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  icon?: React.ReactNode;
  iconRight?: React.ReactNode;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    { variant = 'ghost', size = 'md', icon, iconRight, children, ...rest },
    ref,
  ) {
    return (
      <StyledBtn ref={ref} variant={variant} size={size} {...rest}>
        {icon}
        {children}
        {iconRight}
      </StyledBtn>
    );
  },
);
