import { useEffect, useRef, useState } from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

const Wrapper = styled.div`
  background: ${theme.colors.codeBg};
  border: 1px solid ${theme.colors.codeBorder};
  border-radius: ${theme.borderRadius.md};
  padding: ${theme.spacing.lg};
  margin: ${theme.spacing.lg} 0;
  overflow-x: auto;
  text-align: center;
  svg { max-width: 100%; }
`;

const ErrorBox = styled.div`
  color: #f85149;
  font-family: ${theme.typography.fontFamilyMono};
  font-size: ${theme.typography.fontSizeSm};
  white-space: pre-wrap;
`;

const Fallback = styled.pre`
  background: ${theme.colors.codeBg};
  border: 1px solid ${theme.colors.codeBorder};
  border-radius: ${theme.borderRadius.md};
  padding: ${theme.spacing.md};
  margin: ${theme.spacing.lg} 0;
  overflow-x: auto;
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 12.5px;
  color: ${theme.colors.mainTextMuted};
  white-space: pre-wrap;
`;

let mermaidInitialized = false;

export function MermaidBlock({ code }: { code: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [empty, setEmpty] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setError(null);
    setEmpty(false);

    // Skip wholly-empty input so we don't leave a ghost wrapper on the page.
    if (!code.trim()) {
      setEmpty(true);
      return;
    }

    // LLMs sometimes emit content inside a ```mermaid fence that isn't a
    // real Mermaid diagram — mermaid.render then succeeds but returns an
    // SVG with near-zero geometry. Short-circuit before we even try, by
    // checking the first non-empty line declares a known diagram type.
    const VALID_TYPES = /^(?:---[\s\S]*?---\s*)?(?:graph|flowchart|sequenceDiagram|classDiagram|stateDiagram(?:-v2)?|erDiagram|pie|gantt|journey|mindmap|gitGraph|sankey(?:-beta)?|quadrantChart|requirementDiagram|timeline|xychart-beta|block-beta|C4Context|C4Container|C4Component|C4Dynamic|C4Deployment)\b/;
    const firstMeaningful = code.trim().split(/\r?\n/)[0]?.trim() ?? '';
    if (!VALID_TYPES.test(firstMeaningful)) {
      setEmpty(true);
      return;
    }

    async function render() {
      const mermaid = (await import('mermaid')).default;
      if (!mermaidInitialized) {
        mermaid.initialize({
          startOnLoad: false,
          theme: 'dark',
          themeVariables: {
            background: theme.colors.codeBg,
            primaryColor: theme.colors.accent,
            primaryTextColor: theme.colors.mainText,
            lineColor: theme.colors.border,
          },
        });
        mermaidInitialized = true;
      }
      if (!ref.current || cancelled) return;
      try {
        const id = `mermaid-${Math.random().toString(36).slice(2)}`;
        const { svg } = await mermaid.render(id, code);
        if (cancelled || !ref.current) return;

        ref.current.innerHTML = svg;

        // Belt-and-braces: after layout, if the rendered SVG has effectively
        // zero geometry (mermaid "succeeded" with an empty diagram), fall
        // back to the raw source instead of leaving a ghost bordered box.
        requestAnimationFrame(() => {
          if (cancelled || !ref.current) return;
          const svgEl = ref.current.querySelector('svg');
          if (!svgEl) {
            setEmpty(true);
            return;
          }
          const bb = svgEl.getBoundingClientRect();
          if (bb.width < 40 || bb.height < 40) {
            setEmpty(true);
          }
        });
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : String(err));
      }
    }
    render();
    return () => { cancelled = true; };
  }, [code]);

  if (error) return <Wrapper><ErrorBox>Mermaid error: {error}</ErrorBox></Wrapper>;
  if (empty) return <Fallback>{code.trim()}</Fallback>;
  return <Wrapper ref={ref} />;
}

export default MermaidBlock;
