// ─── CSS variable references ─────────────────────────────────────────────────

type ColorKey = keyof typeof darkColors;

const VAR_PREFIX = '--at-';

function buildColorVars(): Record<ColorKey, string> {
  const vars = {} as Record<ColorKey, string>;
  for (const key of Object.keys(darkColors) as ColorKey[]) {
    vars[key] = `var(${VAR_PREFIX}${key})`;
  }
  return vars;
}

/** Generate a CSS string of custom property declarations for a given mode. */
export function generateCSSVariables(mode: 'dark' | 'light'): string {
  const palette = mode === 'dark' ? darkColors : lightColors;
  return (Object.keys(palette) as ColorKey[])
    .map((key) => `${VAR_PREFIX}${key}: ${palette[key]};`)
    .join('\n  ');
}

/** Raw palette values — used by ThemeContext to inject CSS variables. */
export { darkColors, lightColors };

