    react: `const { useState } = React;

interface Todo {
  id: number;
  text: string;
  done: boolean;
}

let nextId = 4;

function App() {
  const [todos, setTodos] = useState<Todo[]>([
    { id: 1, text: 'Build something awesome', done: true },
    { id: 2, text: 'Add TypeScript types', done: false },
    { id: 3, text: 'Deploy to production', done: false },
  ]);
  const [input, setInput] = useState('');

  const add = () => {
    const text = input.trim();
    if (!text) return;
    setTodos(prev => [...prev, { id: nextId++, text, done: false }]);
    setInput('');
  };

  const toggle = (id: number) =>
    setTodos(prev => prev.map(t => t.id === id ? { ...t, done: !t.done } : t));

  const remove = (id: number) =>
    setTodos(prev => prev.filter(t => t.id !== id));

  const done = todos.filter(t => t.done).length;

  return (
    <div className="app">
      <h2>React Todo</h2>
      <div className="row">
        <input
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && add()}
          placeholder="Add a task…"
        />
        <button onClick={add}>Add</button>
      </div>
      <ul>
        {todos.map(todo => (
          <li key={todo.id} className={todo.done ? 'done' : ''}>
            <span className="check" onClick={() => toggle(todo.id)}>
              {todo.done ? '✅' : '⬜'}
            </span>
            <span className="text" onClick={() => toggle(todo.id)}>{todo.text}</span>
            <span className="del" onClick={() => remove(todo.id)}>×</span>
          </li>
        ))}
      </ul>
      <p className="stats">{done}/{todos.length} completed</p>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')!).render(<App />);`,
