import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

/**
 * Horizontal toolbar used in the Layout top bar.
 *
 * Groups action buttons (`<Button>`, `<IconButton>`, `<Dropdown>`) with
 * consistent spacing. Render this inside the `topBarRight` prop — the
 * shell's `ShellCluster` (locale/theme/profile) sits after it.
 *
 * ```tsx
 * <Layout topBarRight={
 *   <>
 *     <Toolbar>
 *       <Button variant="ghost">New</Button>
 *       <Dropdown trigger={<Button variant="ghost" iconRight={<ChevronDown />}>Saved</Button>}>
 *         {docs.map(d => <DropdownItem key={d.id}>{d.name}</DropdownItem>)}
 *       </Dropdown>
 *       <Button variant="accent" icon={<Save size={13} />}>Save</Button>
 *       <Button variant="success" icon={<Play size={13} />}>Run</Button>
 *     </Toolbar>
 *     {topBarRight}
 *   </>
 * } />
 * ```
 */
export const Toolbar = styled.div`
  display: flex;
  align-items: center;
  gap: ${theme.spacing.sm};
`;

export const ToolbarDivider = styled.span`
  width: 1px;
  height: 20px;
  background: ${theme.colors.border};
  flex-shrink: 0;
`;
