import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import rehypeRaw from 'rehype-raw';
import {
  MermaidBlock,
  ChartBlock,
  CodeBlock,
  Callout,
} from '@atlantis/blog';
import type { CalloutType } from '@atlantis/blog';

// ── remark plugin: GitHub-style callouts ─────────────────────────────────────
// Matches both the canonical blockquote form (`> [!NOTE] …`) and the plain
// paragraph form (`[!NOTE] …`) the LLM often emits when it forgets the `>`.
// The bracket tag is stripped and the host node is rewritten to a
// `<div data-callout="TYPE">` so `MarkdownBody`'s `div` component swaps in
// the Atlantis `Callout`.
function remarkCallouts() {
  const CALLOUT_RE = /^\[!(NOTE|TIP|WARNING|CAUTION|IMPORTANT)\]\s*/i;

  return (tree: any) => {
    function tagNode(host: any, firstPara: any, type: string) {
      // Strip the leading `[!TYPE]` tag from the first text node; drop the
      // text node entirely if nothing is left so the Callout body doesn't
      // render an empty paragraph.
      const inline = firstPara.children?.[0];
      if (inline?.type === 'text') {
        inline.value = inline.value.replace(CALLOUT_RE, '');
        if (!inline.value.trim() && firstPara.children.length === 1) {
          firstPara.children.shift();
        }
      }
      host.data = host.data ?? {};
      host.data.hName = 'div';
      host.data.hProperties = { 'data-callout': type.toUpperCase() };
    }

    function walk(node: any) {
      // Canonical GFM form: `> [!NOTE] body`
      if (node.type === 'blockquote') {
        const first = node.children?.[0];
        if (first?.type === 'paragraph') {
          const inline = first.children?.[0];
          const m = inline?.type === 'text' && inline.value?.match(CALLOUT_RE);
          if (m) tagNode(node, first, m[1]);
        }
      }

      // Lenient form the LLM tends to emit: plain paragraph starting with `[!TYPE]`.
      if (node.type === 'paragraph') {
        const inline = node.children?.[0];
        const m = inline?.type === 'text' && inline.value?.match(CALLOUT_RE);
        if (m) {
          // Wrap the paragraph's remaining children in an inner paragraph so
          // `<Callout>`'s body gets a `<p>` to style normally.
          const innerKids = [...node.children];
          node.children = [{ type: 'paragraph', children: innerKids }];
          tagNode(node, node.children[0], m[1]);
          // Strip tag from the (now inner) paragraph's first text node.
          const innerFirst = innerKids[0];
          if (innerFirst?.type === 'text') {
            innerFirst.value = innerFirst.value.replace(CALLOUT_RE, '');
            if (!innerFirst.value.trim() && innerKids.length === 1) {
              innerKids.shift();
            }
          }
          return; // don't recurse into the freshly wrapped children
        }
      }

      node.children?.forEach(walk);
    }
    walk(tree);
  };
}

// ── Scoped markdown styles ────────────────────────────────────────────────────
// Compact rendering tuned for chat bubbles and inline command-palette answers.

